const item = $input.first().json;
let b = item.body ?? item;
if (typeof b === 'string') {
  try { b = JSON.parse(b); } catch (e) {
    throw new Error('Webhook body must be valid JSON');
  }
}
const dealId = b.hubspot_deal_id ?? b.deal_id;
const slug = b.project_slug;
if (!dealId && !slug) { throw new Error('hubspot_deal_id or project_slug required'); }

function normDue(d) {
  if (d == null || d === '') return undefined;
  const s = String(d).trim();
  if (!s) return undefined;
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  const t = Date.parse(s);
  if (Number.isNaN(t)) return s;
  return new Date(t).toISOString().slice(0, 10);
}

const descRaw =
  (b.description && String(b.description).trim()) ||
  (b.hs_title && String(b.hs_title).trim()) ||
  (b.hs_comments && String(b.hs_comments).trim()) ||
  (b.name && String(b.name).trim()) ||
  (b.subject && String(b.subject).trim()) ||
  'Invoice';

const data = {
  invoice_number: String(b.invoice_number ?? ''),
  description: descRaw,
  amount_cents: Math.round(Number(b.amount_cents ?? b.amountCents ?? 0)),
  status: b.status || 'pending',
};
const allowed = ['paid', 'pending', 'overdue', 'void'];
if (allowed.indexOf(data.status) === -1) data.status = 'pending';
if (b.sku) data.sku = String(b.sku);
const nd = normDue(b.due_date ?? b.hs_due_date);
if (nd) data.due_date = nd;

const hsInvId = b.hubspot_invoice_id ?? b.hs_invoice_id ?? b.invoice_id;
if (hsInvId) data.hubspot_invoice_id = String(hsInvId);

if (b.currency) { const cur = String(b.currency).toLowerCase().replace(/[^a-z]/g, '').slice(0, 3); if (cur) data.currency = cur; }
if (b.paid_at) data.paid_at = String(b.paid_at);

function normBillingPhase(v) {
  if (v == null || v === '') return undefined;
  const t = String(v).trim().toLowerCase();
  if (!t) return undefined;
  const c = t.replace(/[\s\-+]/g, '_').replace(/_+/g, '_');
  if (c === 'deposit' || t.includes('deposit')) return 'deposit';
  if (c === 'build_qa' || c === 'buildqa' || (t.includes('build') && t.includes('qa'))) return 'build_qa';
  if (c === 'handoff' || c === 'hand_off' || t.includes('handoff') || t.includes('hand off')) return 'handoff';
  if (c === 'maintenance' || t.includes('maintenance') || t.includes('retainer')) return 'maintenance';
  return undefined;
}
function normBillingKind(v, phase) {
  if (v != null && v !== '') {
    const t = String(v).trim().toLowerCase();
    if (t.includes('recurring')) return 'recurring_maintenance';
    if (t.includes('project') && t.includes('milestone')) return 'project_milestone';
    if (t === 'recurring_maintenance' || t === 'project_milestone') return t;
  }
  if (phase === 'maintenance') return 'recurring_maintenance';
  return 'project_milestone';
}
const phaseRaw = b.billing_phase ?? b.iw_billing_phase ?? b.properties?.iw_billing_phase;
const kindRaw = b.billing_kind ?? b.iw_billing_kind ?? b.properties?.iw_billing_kind;
const phase = normBillingPhase(phaseRaw);
if (phase) data.billing_phase = phase;
const kind = normBillingKind(kindRaw, phase);
data.billing_kind = kind;
if (b.milestone_order === 1 || b.milestone_order === 2 || b.milestone_order === 3) data.milestone_order = b.milestone_order;
const sp0 = normDue(b.service_period_start ?? b.iw_service_period_start ?? b.properties?.iw_service_period_start);
const sp1 = normDue(b.service_period_end ?? b.iw_service_period_end ?? b.properties?.iw_service_period_end);
if (sp0) data.service_period_start = sp0;
if (sp1) data.service_period_end = sp1;
const mgk = b.maintenance_group_key ?? b.iw_maintenance_group_key ?? b.properties?.iw_maintenance_group_key;
if (mgk) data.maintenance_group_key = String(mgk).trim();
data.external_source = 'hubspot';
const extId = b.external_object_id ?? b.hubspot_invoice_id ?? b.hs_invoice_id ?? b.invoice_id;
if (extId) data.external_object_id = String(extId);

const base = { action: 'add_invoice', data };
if (dealId) base.hubspot_deal_id = String(dealId);
else base.project_slug = String(slug);
return [{ json: { portalPayload: base } }];

const j = $input.first().json;
const statusCode = j.statusCode ?? j.status ?? 0;
const raw = j.body !== undefined && j.body !== null ? j.body : (j.data !== undefined ? j.data : '');
const str = typeof raw === 'string' ? raw : (typeof raw === 'object' ? JSON.stringify(raw) : String(raw));
const t = str.trim();
if (!t) {
  return [{ json: { ok: false, statusCode, error: 'empty_response' } }];
}
try {
  const parsed = JSON.parse(t);
  return [{ json: typeof parsed === 'object' && parsed !== null ? { ...parsed, statusCode } : { result: parsed, statusCode } }];
} catch (e) {
  return [{ json: { ok: false, statusCode, error: 'response_not_json', message: e.message, rawPreview: t.slice(0, 4000) } }];
}

